WITH cleaned AS (SELECT id, supplier_name, country, city, UPPER(supplier_name) supplier_name_upper, COALESCE(city, 'NONE') city_clean FROM suppliers WHERE city IS NOT NULL) SELECT country, SORT_ARRAY(COLLECT_SET(country)) AS country_list, COUNT(DISTINCT country) AS distinct_countries, COUNT(*) FILTER (WHERE country = 'US') AS us_rows, COUNT(*) AS row_count, SORT_ARRAY(COLLECT_SET(country)) AS country_list_2, SIZE(COLLECT_SET(city)) AS num_cities FROM cleaned GROUP BY country HAVING SIZE(COLLECT_SET(city)) < 1000 ORDER BY us_rows DESC NULLS LAST;
